import type { ScanReport } from '../../../packages/contracts/src/index.js';
const escape = (value:unknown) => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
export function reportHtml(report:ScanReport):string {
  return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'"><title>SkillGate · ${escape(report.name)}</title><style>body{font:16px/1.6 system-ui;max-width:880px;margin:40px auto;padding:24px;color:#142f2c;background:#f7f8f4}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:white;border:1px solid #ccd9d4;padding:20px}h1{font-size:30px}</style><h1>SkillGate Finance · ${escape(report.name)}</h1><p>Decision: <strong>${escape(report.decision)}</strong> · Coverage: ${escape(report.coverage.status)}</p><p>Installation-time analysis only. The absence of findings does not prove that the skill is safe.</p><pre>${escape(JSON.stringify(report,null,2))}</pre></html>`;
}
